<script setup lang="ts">
import { onScopeDispose, ref } from 'vue';
import { api, asApiError, type ApiError } from '../api/client';
import { contract, modeNames, paymentModes, type Policy, type PolicyUpdate } from '../domain/m3';
import { formatFen } from '../domain/m1';
import { useSessionStore } from '../stores/session';
import ErrorPanel from '../components/ErrorPanel.vue';
import StatusBadge from '../components/StatusBadge.vue';
import PaymentNavigation from '../components/PaymentNavigation.vue';
const session=useSessionStore();const policy=ref<Policy|null>(null);const draft=ref<PolicyUpdate|null>(null);const loading=ref(false);const pending=ref(false);const confirm=ref(false);const error=ref<ApiError|null>(null);const notice=ref('');
let revision=0;let signature='';let key='';onScopeDispose(()=>revision++);
const fields=[['maxSingleFen','租户单笔上限（分）'],['maxDailyFen','租户每日上限（分）'],['maxStoreSingleFen','每店单笔上限（分）'],['maxStoreDailyFen','每店每日上限（分）'],['minEstimatedProfitFen','最低预计利润（分）']] as const;
function set(value:Policy){policy.value=value;const {globalPaused,usedDailyFen,runtimeMode,...editable}=value;void globalPaused;void usedDailyFen;void runtimeMode;draft.value=editable;}
async function load(){const current=++revision;loading.value=true;error.value=null;confirm.value=false;draft.value=null;policy.value=null;try{const value=await api.getPaymentPolicy();if(current===revision)set(value);}catch(cause){if(current===revision)error.value=asApiError(cause);}finally{if(current===revision)loading.value=false;}}
function review(){if(!pending.value&&draft.value&&session.can('paymentPolicy.manage')&&contract<PolicyUpdate>('M3PolicyUpdate')(draft.value))confirm.value=true;}
async function save(){if(pending.value||!confirm.value||!draft.value||!session.can('paymentPolicy.manage')||!contract<PolicyUpdate>('M3PolicyUpdate')(draft.value))return;const current=revision;const body={...draft.value};const next=JSON.stringify(body);if(next!==signature){signature=next;key=globalThis.crypto.randomUUID();}pending.value=true;error.value=null;try{const value=await api.updatePaymentPolicy(body,key);if(current===revision){set(value);confirm.value=false;notice.value='Mock 支付策略已保存并记录审计；后台仍需逐笔核验门禁。';}}catch(cause){if(current===revision)error.value=asApiError(cause);}finally{if(current===revision)pending.value=false;}}
void load();
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">支付中心 / 策略</p><h1>支付策略</h1><p class="muted">仅 Mock 可测试 / 生产不可用 · 不收集支付凭据</p></div><el-button :disabled="pending" :loading="loading" @click="load">刷新最新策略</el-button></div><PaymentNavigation /><div class="freeze-note"><h2>自动付款仅运行合成 Mock</h2><p>真实 Provider 未审批、授权与准入通过前始终不可用。租户暂停和平台总停付是独立门禁，已在途付款仍可只读查询。</p></div><div v-if="loading" class="panel data-state" role="status"><el-skeleton :rows="5" animated /><p>正在读取支付策略…</p></div><ErrorPanel v-if="error&&!confirm" :error="error" title="支付策略读取或保存失败"><el-button :disabled="pending" @click="load">重试读取</el-button></ErrorPanel><section v-if="draft&&policy" class="panel editor-panel"><div class="panel-heading"><div><h2>当前租户支付规则</h2><p>当前版本 {{ policy.version }} · 保存前需再次确认</p></div><StatusBadge :status="policy.isPaused?'PAUSED':'ACTIVE'" /></div><dl class="order-facts"><div><dt>UTC 日占用 / 租户日上限</dt><dd>{{ formatFen(policy.usedDailyFen) }} / {{ formatFen(policy.maxDailyFen) }} CNY</dd></div><div><dt>平台总停付（只读）</dt><dd>{{ policy.globalPaused?'已暂停所有新付款':'未开启' }}</dd></div><div><dt>平台硬上限</dt><dd>单笔 ¥1,000.00 / UTC 日 ¥10,000.00，取更小值</dd></div></dl><form data-testid="payment-policy-form" class="policy-form" @submit.prevent="review"><label>付款模式<select v-model="draft.mode" name="mode" :disabled="pending"><option v-for="mode in paymentModes" :key="mode" :value="mode">{{ mode }} · {{ modeNames[mode] }}</option></select></label><label v-for="[field,label] in fields" :key="field">{{ label }}<input v-model.number="draft[field]" :name="field" type="number" min="0" max="1000000000000" step="1" required :disabled="pending" /></label><label class="checkbox-label"><input v-model="draft.isPaused" name="isPaused" type="checkbox" :disabled="pending" />紧急暂停所有新付款</label><label class="checkbox-label"><input v-model="draft.newSupplierFirstOrderManual" name="newSupplierFirstOrderManual" type="checkbox" :disabled="pending" />RULE_BASED 新供应商首次付款转人工</label><el-button data-testid="save-payment-policy" native-type="submit" type="primary" :disabled="pending||!contract<PolicyUpdate>('M3PolicyUpdate')(draft)">保存 Mock 策略</el-button></form><p class="help-text muted">金额为非负整数分。每日预算按 UTC 统计；NEW、PAYING、UNKNOWN 预占与已付金额仍占用额度，明确失败才释放。自动付款仍要求有效 Mock 签约、正确账号主体、销售状态、已确认映射、密文能力及最低利润。</p><p v-if="notice" class="success-note" role="status">{{ notice }}</p></section><el-dialog v-model="confirm" title="确认保存 Mock 支付策略" width="520px" :close-on-click-modal="false" :close-on-press-escape="!pending" :show-close="!pending"><p>模式 {{ draft?.mode }} · {{ draft?.isPaused?'暂停所有新付款':'允许符合门禁的 Mock 新付款' }}</p><p v-if="draft" class="help-text">单笔 {{ formatFen(draft.maxSingleFen) }} / 日 {{ formatFen(draft.maxDailyFen) }} CNY。修改策略可能启用后台合成付款，请核对限额与利润；真实支付继续关闭。</p><ErrorPanel v-if="error" :error="error"><p v-if="error.status===409" class="help-text">请关闭弹窗并刷新最新版本后重新确认。</p></ErrorPanel><template #footer><el-button :disabled="pending" @click="confirm=false">取消</el-button><el-button data-testid="confirm-payment-policy" type="primary" :loading="pending" :disabled="pending" @click="save">确认保存策略</el-button></template></el-dialog></div></template>
